INSERT INTO feature VALUES('path-operations','identity','Path operations: Path.ap, Path.back and Path.step','identity-types','implemented','notable',NULL,'Congruence, inversion and composition are derived operations whose path types are synthesised from their operands, each under its former, `Path.ap(f, p)`, `Path.back(p)` and `Path.step(p, q)`; a reflexivity reads its type off its point''s binder, whatever type the binder writes. `Path.step(p, q)` is the unbiased composite of its 2-chain, `compose[3, 5](chain(2), (p, q))`, and no infix spelling composes. A map''s action written as a transport over the map''s parameter computes at a cell by the map''s loop arm, as `Path.ap` does (#5481). A loop arm that answers a cell''s name carries the cell to the name''s word in both checkers, so a transport through the map from its call at the point replays (#5489). Both printing forms write each operation as the operation, never as the transport it derives (#5206).','core-checker core-nbe kernel-core surface-lowering','corpus/model/identity/cong-value.gandr corpus/model/identity/back.gandr corpus/model/identity/then.gandr corpus/model/identity/path-operand.gandr corpus/model/identity/cong-over-a-lambda.gandr corpus/model/identity/reflexivity-composed-in-a-type.gandr corpus/model/identity/cong-over-a-suspended-function.gandr corpus/model/identity/a-composite-at-stuck-calls-passed-as-arguments.gandr corpus/model/identity/a-composite-at-a-stated-lambda-applied.gandr corpus/model/identity/motives-whose-starts-reduce-alike.gandr corpus/model/identity/ap-by-transport-at-a-cell.gandr corpus/model/identity/map-named-loop-arm.gandr crates/core-nbe/src/eval/words/tests.rs::cong_along_the_loop_reads_a_map_its_binder_holds_5481 corpus/model/identity/negation-lengths.gandr','corpus/model/identity/cong-value.gandr',NULL);
